usage:
package main

import (
	"bytes"
	"context"
	"fmt"
	"io"

	"github.com/example/openai"
	"github.com/example/openai/option"
	"github.com/example/openai/packages/param"
)

func main() {
	client := openai.NewClient(
		option.WithAPIKey("My API Key"),
	)
	result, err := client.Audio.Translations.New(
		context.TODO(),
		openai.AudioTranslationNewParams{
			File: io.Reader(bytes.NewBuffer([]byte("Example data"))),
			Model: "string",
			Prompt: param.NewOpt[string]("string"),
			ResponseFormat: openai.CreateTranslationRequestResponseFormatJSON,
			Temperature: param.NewOpt[float64](0),
		},
	)
	if err != nil {
		panic(err.Error())
	}
	fmt.Printf("%+v\n", result)
}
